CREATE FUNCTION public.has_paid_bell(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_allowed(_user) AND EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='membership' AND payable_amount=100 AND status='approved' AND received_at<=now() AND ends_at>now()) $$;
REVOKE ALL ON FUNCTION public.has_paid_bell(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_paid_bell(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.paid_alert_ready(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_paid_bell(_user) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=_user AND bell_activated_at IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION public.my_prime99() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('active',public.has_prime99(auth.uid()),'bell_active',public.has_paid_bell(auth.uid()),'alerts_ready',public.paid_alert_ready(auth.uid()),'ends_at',(SELECT max(ends_at) FROM public.prime99_payments WHERE user_id=auth.uid() AND payment_purpose='membership' AND status='approved'),'alerts_start_at',(SELECT min(received_at) FROM public.prime99_payments WHERE user_id=auth.uid() AND payable_amount=100 AND payment_purpose='membership' AND status='approved' AND ends_at>now()),'amount',100) $$;
CREATE OR REPLACE FUNCTION public.validate_current_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.payment_purpose='membership' AND NEW.payable_amount NOT IN(100,public.my_membership_price()) THEN RAISE EXCEPTION 'PAYMENT_PRICE_MISMATCH'; END IF; IF NEW.received_at IS NOT NULL OR NEW.ends_at IS NOT NULL OR NEW.alerts_start_at IS NOT NULL OR NEW.used_post_id IS NOT NULL OR NEW.status<>'pending' OR NEW.reviewed_by IS NOT NULL OR NEW.review_note<>'' THEN RAISE EXCEPTION 'PAYMENT_REVIEW_REQUIRED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.review_prime99(_id uuid,_approve boolean,_note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.prime99_payments; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT * INTO p FROM public.prime99_payments WHERE id=_id FOR UPDATE; IF p.id IS NULL OR p.status<>'pending' THEN RAISE EXCEPTION 'NO_PENDING_PAYMENT'; END IF; PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; UPDATE public.prime99_payments SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,received_at=CASE WHEN _approve THEN now() ELSE NULL END,ends_at=CASE WHEN _approve AND p.payment_purpose='membership' THEN now()+interval '1 month' ELSE NULL END,alerts_start_at=CASE WHEN _approve AND p.payment_purpose='membership' THEN now() ELSE NULL END,reviewed_by=auth.uid(),review_note=left(coalesce(_note,''),500) WHERE id=_id; IF _approve AND p.payment_purpose='membership' THEN INSERT INTO public.monthly_post_periods(user_id,starts_at,ends_at) VALUES(p.user_id,now(),now()+interval '1 month') ON CONFLICT(user_id) DO UPDATE SET starts_at=excluded.starts_at,ends_at=excluded.ends_at WHERE monthly_post_periods.ends_at<=now(); PERFORM public.confirm_referral_cash(p.user_id,p.reference,p.payable_amount::bigint*100); END IF; END $$;
CREATE OR REPLACE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND CASE WHEN _post IS NULL THEN _other=public.support_admin_id() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.service_chat_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)) OR EXISTS(SELECT 1 FROM public.messages WHERE post_id IS NULL AND ((sender_id=auth.uid() AND receiver_id=_other) OR (receiver_id=auth.uid() AND sender_id=_other))) ELSE EXISTS(SELECT 1 FROM public.post_chat_pairs WHERE post_id=_post AND ((member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other))) END $$;
CREATE OR REPLACE FUNCTION public.ring_post(_post_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; caller uuid:=auth.uid(); BEGIN IF caller IS NULL OR NOT public.account_allowed(caller) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; SELECT * INTO p FROM public.posts WHERE id=_post_id AND status='active' AND (visible_after IS NULL OR visible_after<=now()) AND (job_expires_at IS NULL OR job_expires_at>now()) AND public.account_allowed(user_id); IF p.id IS NULL OR p.user_id=caller THEN RAISE EXCEPTION 'POST_UNAVAILABLE'; END IF; UPDATE public.profiles SET bell_activated_at=coalesce(bell_activated_at,now()) WHERE id=caller; INSERT INTO public.post_chat_pairs(post_id,member_id,owner_id) VALUES(p.id,caller,p.user_id) ON CONFLICT DO NOTHING; PERFORM set_config('app.bell_notice','interest',true); PERFORM 1 FROM public.profiles WHERE id=p.user_id FOR UPDATE; IF public.can_notify(p.user_id) THEN INSERT INTO public.notifications(user_id,post_id,message) VALUES(p.user_id,p.id,'మీ ప్రకటన గంటను ఒకరు నొక్కారు; సంభాషణలో స్పందించండి.'); END IF; IF NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id AND sender_id=caller AND receiver_id=p.user_id) THEN INSERT INTO public.messages(sender_id,receiver_id,post_id,body) VALUES(caller,p.user_id,p.id,'హాయ్ · Hi'); END IF; PERFORM set_config('app.bell_notice','',true); RETURN p.user_id; END $$;
CREATE OR REPLACE FUNCTION public.ring_service(_owner uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF NOT public.has_paid_bell(auth.uid()) THEN RAISE EXCEPTION 'PAID_BELL_REQUIRED'; END IF; IF auth.uid()=_owner OR NOT public.account_allowed(_owner) OR NOT EXISTS(SELECT 1 FROM public.service_profiles WHERE user_id=_owner AND published) THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; INSERT INTO public.service_chat_pairs(member_id,owner_id) VALUES(auth.uid(),_owner) ON CONFLICT DO NOTHING; UPDATE public.profiles SET bell_activated_at=coalesce(bell_activated_at,now()) WHERE id=auth.uid(); PERFORM 1 FROM public.profiles WHERE id=_owner FOR UPDATE; IF public.can_notify(_owner) THEN INSERT INTO public.notifications(user_id,message) VALUES(_owner,'మీ సేవపై సమాచారం కోరారు; సంభాషణలో స్పందించండి.'); END IF; IF NOT EXISTS(SELECT 1 FROM public.messages WHERE sender_id=auth.uid() AND receiver_id=_owner AND post_id IS NULL) THEN INSERT INTO public.messages(sender_id,receiver_id,body) VALUES(auth.uid(),_owner,'హాయ్ · Hi'); END IF; RETURN _owner; END $$;
CREATE OR REPLACE FUNCTION public.notify_nearby_vehicles(_post uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; RETURN 0; END $$;
COMMENT ON FUNCTION public.notify_nearby_vehicles(uuid) IS 'DEPRECATED: listing bells target only the selected post owner; no nearby-owner fanout.';